SELECT CASE WHEN status_bits >= 11 THEN 'PREMIUM' ELSE 'STANDARD' END AS status_bits_tier, device_code, COUNT(*) AS row_count, MIN(reading_ts) AS first_seen, SUM(CASE WHEN device_code = 'DV-04' THEN pressure ELSE 0 END) AS dv_04_pressure, RANK() OVER (PARTITION BY CASE WHEN status_bits >= 11 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY SUM(CASE WHEN device_code = 'DV-04' THEN pressure ELSE 0 END) DESC) AS dv_04_pressure_rank FROM device_readings GROUP BY CASE WHEN status_bits >= 11 THEN 'PREMIUM' ELSE 'STANDARD' END, device_code ORDER BY row_count NULLS LAST;
